Keybinds.codeToKey = function(code) {
  var key = null;

  if (code == 8) {
    return null;
  }

  if (code == 27) {
    key = 'Esc';
  }
  else if (code == 37) {
    key = '&#8592;';
  }
  else if (code == 39) {
    key = '&#8594;';
  }
  else if (code >= 65 && code <= 90) {
    key = String.fromCharCode(code).toUpperCase();
  }

  return key;
};

